SELECT country, CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, city, COUNT(rating) AS rating_count FROM suppliers WHERE country = 'JP' OR city NOT IN ('Berlin', 'Tokyo') GROUP BY country, CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END, city ORDER BY rating_count DESC, country, rating_bucket, city LIMIT 50;
